mapper.select:
select A.SEQ_ID seqId, CASE WHEN B.MATCH_STATUS IS NULL THEN #{TRD_MATCH_STATUS_01} ELSE B.MATCH_STATUS END matchStatus, ROUND(F.MARCH_QTY / A.SHARE_AMT,4) matchProgress, A.TRADE_MARKET tradeMarket, A.TRADE_MARKET_MODE tradeMarketMode, A.APPLY_TRADE_ID applyTradeId, A.SEC_ACCT_ID secAcctId, C.SEC_ACCT_NAME secAcctName, A.SEC_TYPE secType, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_MARKET_ID END finprodMarketId, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ID END finprodId, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ABBR END finprodAbbr, A.FINPROD_TYPE2 finprodType2,
A.FINPROD_TYPE,
A.SEAT_NUMBER seatNumber, A.TRADE_PLAT tradePlat, A.PS ps, NVL(A.SHARE_AMT,0) - NVL(F.MARCH_QTY,0) remainNum, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NVL(A.SHARE_AMT,0) - NVL(F.MARCH_AMT,0) ELSE NVL(A.FPRICE_AMT,0) - NVL(F.MARCH_AMT,0) END remainAmount, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN A.UNIT_CPRICE ELSE A.UNIT_FPRICE END unitFprice, A.UNIT_CPRICE unitCprice, A.UNIT_INT unitInt, A.CCY ccy, A.TRADE_DATE dealDate, A.TRADE_DATE tradeDate, A.SETTLE_DATE settleDate, D.ACCT_NO acctNo, D.ACCT_NAME acctName, NVL(A.STAMP_FEE,0) stampFee, NVL(A.JSF_AMT,0) jsfAmt, NVL(A.GHF_AMT,0) ghfAmt, NVL(A.ZGF_AMT,0) zgfAmt, NVL(A.SXF_AMT,0) sxfAmt, NVL(A.SETTLE_FEE,0) settleFee, NVL(A.COMMISSION_AMT,0) commissionAmt, A.TRADE_ID_RAW tradeIdRaw, A.VDATE, A.MDATE, A.TERM_TYPE, A.VPAY_DATE, A.MPAY_DATE, A.SETTLE_MODE, A.SHARE_AMT shareAmt, A.FPRICE_AMT fpriceAmt, A.INT_AMT, A.PRIN_AMT, A.TRADE_AMT, A1.REPO_TYPE repoType, A1.CON_PRICE conPrice, A1.CON_AMT conAmt, A1.R_FINPROD_ID rFinMarketId, E1.FINPROD_ID rFinprodId, A.F_CJBH fCjbh,
A.BUSI_TYPE
from SETTLE_TRANS_DATA_TOTAL A LEFT JOIN SETTLE_TRANS_DATA_TOTAL_STATUS B ON A.SEQ_ID = B.SEQ_NO LEFT JOIN STL_SEC_ACCT_INFO C ON A.SEC_ACCT_ID = C.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO D ON D.ACCT_NO = A.ACCT_NO LEFT JOIN FIN_PRODUCT E ON E.FINPROD_ID = A.FINPROD_ID LEFT JOIN (select T.SEQ_NO, SUM(T.MARCH_QTY) MARCH_QTY,SUM(T.MARCH_AMT) MARCH_AMT from SETTLE_TRANS_DATA_TOTAL_MATCH T GROUP BY T.SEQ_NO) F ON A.SEQ_ID = F.SEQ_NO LEFT JOIN SETTLE_TRANS_DATA_TOTAL_ADD A1 ON A.SEQ_ID = A1.TRADE_ID LEFT JOIN FIN_PRODUCT E1 ON A1.R_FINPROD_ID = E1.FINPROD_MARKET_ID AND E1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10}
A.SEQ_ID NOT IN ( select A2.SEQ_ID from SETTLE_TRANS_DATA_TOTAL A2 INNER JOIN SETTLE_TRANS_DATA_TOTAL_ADD B2 ON A2.SEQ_ID = B2.TRADE_ID WHERE A2.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F03})
AND B2.REPO_TYPE = #{TARGET_BACK_TYPE_H01} AND A2.PS IN (#{PS_T07}) )
AND A.TRADE_MARKET = #{tradeMarket}
AND A.TRADE_PLAT = #{tradePlat}
AND A.PS = #{ps}
AND A.FINPROD_TYPE2 = #{finprodType2}
AND A.SEC_ACCT_ID = #{secAcctNo}
AND (A.APPLY_TRADE_ID IN
null) or A.APPLY_TRADE_ID in (
#{item} )
AND E.FINPROD_MARKET_ID = #{finprodId}
AND A.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
AND A.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND (B.MATCH_STATUS in (#{TRD_MATCH_STATUS_01},#{TRD_MATCH_STATUS_02}) OR B.MATCH_STATUS IS NULL)
AND (B.MATCH_STATUS = #{matchStatus} or B.MATCH_STATUS IS NULL)
AND B.MATCH_STATUS = #{matchStatus}
AND A.FPRICE_AMT >= #{tradeAmt1}
AND A.FPRICE_AMT <= #{tradeAmt2}

SELECT DISTINCT A1.ENTRUST_ID entrustId, D1.TARGET_TYPE targetType, A1.UPDATE_TIME updateTime, #{TRADE_TYPE_02} tradeType, CASE WHEN A1.ENTRUST_CLASS = #{ENTRUST_CLASS_02} THEN det.PORTFOLIO_ID ELSE A1.PORTFOLIO_ID END portfolioId, CASE WHEN A1.ENTRUST_CLASS = #{ENTRUST_CLASS_02} THEN det.PORTFOLIO_NAME ELSE B1.PORTFOLIO_NAME END portfolioName, CASE WHEN A1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} THEN #{SEC_TYPE_01} WHEN A1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} THEN #{SEC_TYPE_06} WHEN A1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06} THEN #{SEC_TYPE_02} WHEN A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) THEN #{SEC_TYPE_09} WHEN A1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F37} THEN #{SEC_TYPE_14} END secType, CASE WHEN A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) THEN NULL ELSE A1.FINPROD_ID END finprodId, A1.FINPROD_TYPE2 finprodType2, CASE WHEN A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) THEN NULL ELSE C1.FINPROD_MARKET_ID END finprodMarketId, A1.ENTRUST_DATE entrustDate, A1.PS ps, A1.TRADE_MARKET tradeMarket, A1.TRADE_PLAT tradePlat, CASE WHEN (A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND A1.PS IN (#{PS_T93},#{PS_T94})) THEN NVL(G1.PLEDGE_NUMBER,0)-NVL(S.MARCH_QTY_EN,0) ELSE NVL(A1.ENTRUST_AMT,0)-NVL(S.MARCH_AMT_EN,0) END entrustAmt, A1.PRICE price, CASE WHEN (A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND A1.PS NOT IN (#{PS_T93},#{PS_T94})) THEN NVL(A1.ENTRUST_AMT,0)-NVL(S.MARCH_AMT_EN,0) WHEN (A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND A1.PS IN (#{PS_T93},#{PS_T94})) THEN NVL(G1.PLEDGE_NUMBER,0)-NVL(S.MARCH_QTY_EN,0) ELSE NVL(A1.ENTRUST_NUM,0) - NVL(S.MARCH_QTY_EN,0) END entrustNum, E1.SEC_ACCT_ID secAcctId, E1.SEC_ACCT_NAME secAcctName, F1.ACCT_NO acctNo, F1.ACCT_NAME acctName, A1.ENTRUST_CLASS entrustClass FROM ETR_ENTRUST A1 LEFT JOIN PTL_PORTFOLIO B1 ON A1.PORTFOLIO_ID = B1.PORTFOLIO_ID LEFT JOIN (SELECT ENTRUST_ID, wm_concat ( ETR_ENTRUST_DETAIL.PORTFOLIO_ID ) PORTFOLIO_ID, wm_concat ( PORTFOLIO_NAME ) PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL LEFT JOIN PTL_PORTFOLIO ON ETR_ENTRUST_DETAIL.portfolio_id = PTL_PORTFOLIO.portfolio_id GROUP BY ENTRUST_ID ) det on det.ENTRUST_ID = A1.ENTRUST_ID LEFT JOIN FIN_PRODUCT C1 ON A1.FINPROD_ID = C1.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD D1 ON D1.ENTRUST_ID = A1.ENTRUST_ID LEFT JOIN (SELECT ENTRUNST_TRADE_ID, NVL(SUM(MARCH_QTY_EN), 0) MARCH_QTY_EN, NVL(SUM(MARCH_AMT_EN), 0) MARCH_AMT_EN FROM SETTLE_TRANS_DATA_TOTAL_MATCH GROUP BY ENTRUNST_TRADE_ID) S ON S.ENTRUNST_TRADE_ID = A1.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO E1 ON E1.SEC_ACCT_ID = D1.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO F1 ON F1.ACCT_NO = E1.TRD_ACCT_ID LEFT JOIN ETR_PLEDGE G1 ON G1.ENTRUST_ID = A1.ENTRUST_ID AND G1.FINPROD_ID = A1.FINPROD_ID WHERE A1.ENTRUST_STATUS = #{ENTRUST_STATUS_03} AND A1.TRADE_MARKET IN (#{TRADE_PLACE_03},#{TRADE_PLACE_04}) AND A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}, #{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10}, #{FINPROD_TYPE_TG_F37})
AND (A1.PORTFOLIO_ID IN
null) or A1.PORTFOLIO_ID in (
#{item} )
AND (A1.FINPROD_TYPE2 IN
null) or A1.FINPROD_TYPE2 in (
#{item} )
AND C1.FINPROD_MARKET_ID = #{finprodId}
AND A1.FINPROD_TYPE2 = #{finprodType1}
AND A1.PS = #{ps}
AND A1.ENTRUST_DATE >= TO_DATE(#{tradeDateBegin}, 'yyyy-mm-dd')
AND A1.ENTRUST_DATE <= TO_DATE(#{tradeDateEnd}, 'yyyy-mm-dd')
AND A1.TRADE_MARKET = #{tradeMarket}
AND A1.ENTRUST_DATE = TO_DATE(#{dealDate}, 'yyyy-mm-dd')
AND D1.SEC_ACCT_ID = #{secAccount}
AND NVL(G1.PLEDGE_NUMBER,0)-NVL(S.MARCH_AMT_EN,0) >= #{remainNum}
AND NVL(A1.ENTRUST_AMT,0)-NVL(S.MARCH_AMT_EN,0) >= #{remainNum}
AND A1.FINPROD_ID = #{termType}
UNION SELECT DISTINCT A1.ENTRUST_ID entrustId, D1.TARGET_TYPE targetType, A1.UPDATE_TIME updateTime, #{TRADE_TYPE_02} tradeType, CASE WHEN A1.ENTRUST_CLASS = #{ENTRUST_CLASS_02} THEN det.PORTFOLIO_ID ELSE A1.PORTFOLIO_ID END portfolioId, CASE WHEN A1.ENTRUST_CLASS = #{ENTRUST_CLASS_02} THEN det.PORTFOLIO_NAME ELSE B1.PORTFOLIO_NAME END portfolioName, #{SEC_TYPE_01} secType, A1.FINPROD_ID, A1.FINPROD_TYPE2, C1.FINPROD_MARKET_ID, A1.ENTRUST_DATE, A1.PS ps, A1.TRADE_MARKET, A1.TRADE_PLAT, NVL(A1.ENTRUST_AMT,0) - NVL(S.MARCH_AMT_EN,0) entrustAmt, A1.PRICE, NVL(A1.ENTRUST_NUM,0) - NVL(S.MARCH_QTY_EN,0) entrustNum, E1.SEC_ACCT_ID, E1.SEC_ACCT_NAME, F1.ACCT_NO, F1.ACCT_NAME, A1.ENTRUST_CLASS FROM ETR_ENTRUST A1 LEFT JOIN PTL_PORTFOLIO B1 ON A1.PORTFOLIO_ID = B1.PORTFOLIO_ID LEFT JOIN (SELECT ENTRUST_ID, SEC_ACCT_ID, wm_concat ( ETR_ENTRUST_DETAIL.PORTFOLIO_ID ) PORTFOLIO_ID, wm_concat ( PORTFOLIO_NAME ) PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL LEFT JOIN PTL_PORTFOLIO ON ETR_ENTRUST_DETAIL.portfolio_id = PTL_PORTFOLIO.portfolio_id GROUP BY ENTRUST_ID, SEC_ACCT_ID ) det on det.ENTRUST_ID = A1.ENTRUST_ID LEFT JOIN FIN_PRODUCT C1 ON A1.FINPROD_ID = C1.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD D1 ON D1.ENTRUST_ID = A1.ENTRUST_ID LEFT JOIN (SELECT ENTRUNST_TRADE_ID, SEC_ACCT_ID, NVL(SUM(MARCH_QTY_EN), 0) MARCH_QTY_EN, NVL(SUM(MARCH_AMT_EN), 0) MARCH_AMT_EN FROM SETTLE_TRANS_DATA_TOTAL_MATCH GROUP BY ENTRUNST_TRADE_ID, SEC_ACCT_ID ) S ON S.ENTRUNST_TRADE_ID = A1.ENTRUST_ID AND S.SEC_ACCT_ID = det.SEC_ACCT_ID LEFT JOIN STL_SEC_ACCT_INFO E1 ON E1.SEC_ACCT_ID = D1.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO F1 ON F1.ACCT_NO = E1.TRD_ACCT_ID WHERE A1.ENTRUST_STATUS = #{ENTRUST_STATUS_03} AND A1.TRADE_MARKET IN (#{TRADE_PLACE_03},#{TRADE_PLACE_04}) AND A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F32})
AND (A1.PORTFOLIO_ID IN
null) or A1.PORTFOLIO_ID in (
#{item} )
AND (A1.FINPROD_TYPE2 IN
null) or A1.FINPROD_TYPE2 in (
#{item} )
AND C1.FINPROD_MARKET_ID = #{finprodId}
AND A1.FINPROD_TYPE2 = #{finprodType1}
AND A1.PS = #{ps}
AND A1.ENTRUST_DATE >= TO_DATE(#{tradeDateBegin}, 'yyyy-mm-dd')
AND A1.ENTRUST_DATE <= TO_DATE(#{tradeDateEnd}, 'yyyy-mm-dd')
AND A1.TRADE_MARKET = #{tradeMarket}
AND A1.ENTRUST_DATE = TO_DATE(#{dealDate}, 'yyyy-mm-dd')
AND det.SEC_ACCT_ID = #{secAccount}

select distinct A.SEQ_NO seqId, A.MATCH_CLASS matchType, A.ENTRUNST_TRADE_ID busiCode, C.TRADE_MARKET tradeMarket, C.APPLY_TRADE_ID applyTradeId, det.PORTFOLIO_ID portfolioId, CASE WHEN D.ENTRUST_CLASS = #{ENTRUST_CLASS_02} THEN det.PORTFOLIO_NAME ELSE det.PORTFOLIO_NAME END portfolioName, CASE WHEN C.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_MARKET_ID END finprodMarketId, C.FINPROD_TYPE2 finprodType2, C.SEC_TYPE secType, CASE WHEN C.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ID END finprodId, C.PS ps, A.MARCH_AMT_EN tradeAmt,
CASE WHEN C.SEC_TYPE = #{SEC_TYPE_09} THEN A.MARCH_AMT_EN ELSE A.MARCH_QTY_EN END tradeNum,
CASE WHEN C.SEC_TYPE = #{SEC_TYPE_09} THEN C.UNIT_CPRICE ELSE C.UNIT_FPRICE END tradePrice , C.DEAL_DATE tradeDate, C.CCY ccy from SETTLE_TRANS_DATA_TOTAL_MATCH A INNER JOIN SETTLE_TRANS_DATA_TOTAL_STATUS B ON A.SEQ_NO = B.SEQ_NO AND B.MATCH_STATUS IN (#{TRD_MATCH_STATUS_1},#{TRD_MATCH_STATUS_2}) INNER JOIN SETTLE_TRANS_DATA_TOTAL C ON A.SEQ_NO = C.SEQ_ID LEFT JOIN ETR_ENTRUST D ON D.ENTRUST_ID = A.ENTRUNST_TRADE_ID LEFT JOIN FIN_PRODUCT E ON E.FINPROD_ID = C.FINPROD_ID LEFT JOIN PTL_PORTFOLIO F ON D.PORTFOLIO_ID = F.PORTFOLIO_ID LEFT JOIN (SELECT ENTRUST_ID, wm_concat ( ETR_ENTRUST_DETAIL.PORTFOLIO_ID ) PORTFOLIO_ID, wm_concat ( PORTFOLIO_NAME ) PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL LEFT JOIN PTL_PORTFOLIO ON ETR_ENTRUST_DETAIL.portfolio_id = PTL_PORTFOLIO.portfolio_id GROUP BY ENTRUST_ID ) det on det.ENTRUST_ID = D.ENTRUST_ID
AND A.MATCH_CLASS = #{matchType}
AND C.APPLY_TRADE_ID = #{dealId}
AND C.TRADE_MARKET = #{tradeMarket}
AND (D.PORTFOLIO_ID IN
null) or D.PORTFOLIO_ID in (
#{item} )
AND A.ENTRUNST_TRADE_ID = #{busiCode}
AND C.SEC_ACCT_ID = #{secAcctNo}
AND D.PS = #{ps}
AND C.FINPROD_TYPE2 = #{finprodType2_hg}
AND C.FINPROD_TYPE2 = #{finprodType2}
AND C.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
AND C.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND E.FINPROD_MARKET_ID = #{finprodId}
AND C.SEC_TYPE = #{secType}
